import re
from collections import deque

def evaluate_expression(text: str) -> int:
    """
    Evaluates an integer arithmetic expression with non-negative integer literals,
    binary +, - and *, unary minus and plus, and parentheses.

    Rules:
    - Whitespace is ignored.
    - * binds tighter than + and -.
    - + and - are left-associative.
    - Unary signs apply to the factor immediately following them.
    - --2 is 2, -2*3 is -6, 2*-3 is -6.

    Raises ValueError for:
    - Empty expression.
    - Missing operand or parenthesis.
    - Two numbers in a row.
    - Any other character.
    """

    # Clean the input: remove all whitespace
    text = re.sub(r'\s+', '', text)

    if not text:
        raise ValueError("Empty expression")

    # Tokenize the expression
    # We need to handle: numbers, operators (+, -, *), and parentheses ((), )
    # Numbers can be multi-digit.
    tokens = []
    i = 0
    while i < len(text):
        char = text[i]
        if char.isdigit():
            # Parse the full number
            j = i
            while j < len(text) and text[j].isdigit():
                j += 1
            num_str = text[i:j]
            tokens.append(('NUM', int(num_str)))
            i = j
        elif char in '+-*()':
            tokens.append((char,))
            i += 1
        else:
            raise ValueError(f"Invalid character: {char}")

    if not tokens:
        raise ValueError("Empty expression")

    # Shunting-yard algorithm to convert infix to postfix (RPN)
    # Operators precedence: * = 2, + = - = 1
    # Left associativity

    output_queue = deque()
    op_stack = deque()

    def get_precedence(op):
        if op == '*':
            return 2
        elif op in '+-':
            return 1
        else:
            return 0

    for token in tokens:
        if isinstance(token, tuple) and token[0] == 'NUM':
            output_queue.append(token[1])
        elif isinstance(token, tuple) and len(token) == 1:
            op = token[0]

            # Handle unary operators (only at start of stack or after '(')
            if not op_stack or op_stack[-1][0] in '()':
                # It's a unary operator
                op_stack.append((op, True))
            else:
                # Binary operator
                while op_stack and get_precedence(op_stack[-1][0]) >= get_precedence(op):
                    top_op = op_stack.pop()
                    output_queue.append(top_op[0])
                op_stack.append((op, False))
        elif isinstance(token, tuple) and len(token) == 2:
            if token[0] == '(':
                op_stack.append(token)
            elif token[0] == ')':
                while op_stack and op_stack[-1][0] != '(':
                    top_op = op_stack.pop()
                    output_queue.append(top_op[0])
                if not op_stack:
                    raise ValueError("Missing opening parenthesis")
                op_stack.pop() # Remove '('

    while op_stack:
        top_op = op_stack.pop()
        if top_op[0] == '(':
            raise ValueError("Missing closing parenthesis")
        output_queue.append(top_op[0])

    # Evaluate the postfix expression
    eval_stack = deque()
    for token in output_queue:
        if isinstance(token, int):
            eval_stack.append(token)
        else:
            if len(eval_stack) < 2:
                raise ValueError("Missing operand")
            right = eval_stack.pop()
            left = eval_stack.pop()

            op = token
            if op == '+':
                result = left + right
            elif op == '-':
                result = left - right
            elif op == '*':
                result = left * right
            else:
                raise ValueError(f"Unknown operator: {op}")

            eval_stack.append(result)

    if len(eval_stack) != 1:
        raise ValueError("Malformed expression")

    return eval_stack.pop()
