def evaluate_expression(text: str) -> int:
    tokens = re.findall(r'(\d+|[-+*()])', text.replace(' ', ''))
    if not tokens:
        raise ValueError("Empty expression")

    # Check for malformed expressions
    if tokens[0] in ('+', '-'):
        raise ValueError("Missing operand at start")
    if tokens[-1] in ('+', '-', '*', ')'):
        raise ValueError("Missing operand at end")
    if tokens[0] == ')':
        raise ValueError("Missing opening parenthesis")

    # Check for two numbers in a row
    for i in range(len(tokens) - 1):
        if tokens[i].isdigit() and tokens[i + 1].isdigit():
            raise ValueError("Two numbers in a row")

    # Check for unmatched parentheses
    paren_count = 0
    for token in tokens:
        if token == '(':
            paren_count += 1
        elif token == ')':
            paren_count -= 1
            if paren_count < 0:
                raise ValueError("Unmatched closing parenthesis")
    if paren_count != 0:
        raise ValueError("Unmatched opening parenthesis")

    # Parse the expression using a stack-based approach
    # We'll use a two-stack approach: one for values and one for operators
    values = []
    operators = []

    # First pass: handle unary operators and parentheses
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token == '(':
            # Push the opening parenthesis to the operator stack
            operators.append(token)
        elif token == ')':
            # Process operators until we find the matching opening parenthesis
            while operators and operators[-1] != '(':
                op = operators.pop()
                if op == '+':
                    values.append(values.pop() + values.pop())
                elif op == '-':
                    values.append(values.pop() - values.pop())
                elif op == '*':
                    values.append(values.pop() * values.pop())
            # Pop the opening parenthesis
            operators.pop()
        elif token in ('+', '-', '*'):
            # Handle unary operators
            if i == 0 or tokens[i - 1] in ('+', '-', '*', ')'):
                # Unary operator
                if token == '-':
                    values.append(-values.pop())
                elif token == '+':
                    values.append(values.pop())
                else:
                    values.append(values.pop())
            else:
                # Binary operator
                operators.append(token)
        else:
            # Number
            values.append(int(token))
        i += 1

    # Process remaining operators
    while operators:
        op = operators.pop()
        if op == '+':
            values.append(values.pop() + values.pop())
        elif op == '-':
            values.append(values.pop() - values.pop())
        elif op == '*':
            values.append(values.pop() * values.pop())

    return values[0]
