def merge_intervals(intervals):
    # Create a copy to avoid modifying the original input
    result = []
    if not intervals:
        return result

    # Sort intervals based on start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    for interval in sorted_intervals:
        if not result:
            result.append(interval)
        else:
            last_interval = result[-1]
            # If current interval overlaps or touches the last one, merge them
            if interval[0] <= last_interval[1]:
                # Update the end of the last interval if needed
                if interval[1] > last_interval[1]:
                    last_interval = [last_interval[0], interval[1]]
                # Since we are using lists, we need to replace the last element
                result.pop()
                result.append(last_interval)
            else:
                # No overlap, add as new interval
                result.append(interval)

    return result
