    tokens: List[Union[Number, str]] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(text[i:j])
            i = j
        elif ch in '+-*()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch}")

