    for i in range(len(tokens) - 1):
        if tokens[i] in '+-*' and tokens[i+1] in '+-*()':
            raise ValueError("Malformed expression: two numbers in a row")

    # Evaluate using two stacks: values and operators
    values: List[Number] = []
    ops: List[str] = []

    def apply_op():
        if not ops:
            return
        op = ops.pop()
        right = values.pop()
        left = values.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)

    for token in tokens:
        if isinstance(token, Number):
            values.append(token)
        elif token in '+-*':
            while ops and ops[-1] in '+-*' and ops[-1] != '(':
                apply_op()
